INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷110·太祖本纪·归藩书与契丹使", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/82a6e88e766f7337f28566c6d64678bb760b98b8/content/books/zizhi-tongjian/vol-290/year-0951/part-02/sources/library/jiuwudaishi-110-january-yun-letter/source.txt", "note": "《旧五代史》卷110·太祖本纪·归藩书与契丹使，段落 jiu-wudaishi-205deb4a7860-p002650；已核上下文及传主，纸本及异文待核。", "id": "80a2082d-34ee-5608-a223-7d645dc17252"}, {"title": "旧五代史·卷110·太祖本纪·邺都任命与隐帝发丧", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/82a6e88e766f7337f28566c6d64678bb760b98b8/content/books/zizhi-tongjian/vol-290/year-0951/part-02/sources/library/jiuwudaishi-110-yedu-funeral/source.txt", "note": "《旧五代史》卷110·太祖本纪·邺都任命与隐帝发丧，段落 jiu-wudaishi-205deb4a7860-p002651；已核上下文及传主，纸本及异文待核。", "id": "5b51fc62-7627-56dc-a90c-a02ed1d0e8f0"}, {"title": "旧五代史·卷135·刘崇传·汉末求子归藩", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/82a6e88e766f7337f28566c6d64678bb760b98b8/content/books/zizhi-tongjian/vol-290/year-0951/part-02/sources/library/jiuwudaishi-135-liu-chong-background/source.txt", "note": "《旧五代史》卷135·刘崇传·汉末求子归藩，段落 jiu-wudaishi-205deb4a7860-p003241；已核上下文及传主，纸本及异文待核。", "id": "6c3b5600-17bd-5704-a1d6-9ab91ac1962b"}, {"title": "旧五代史·卷135·刘崇传·改名与北汉初政", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/82a6e88e766f7337f28566c6d64678bb760b98b8/content/books/zizhi-tongjian/vol-290/year-0951/part-02/sources/library/jiuwudaishi-135-liu-min-accession/source.txt", "note": "《旧五代史》卷135·刘崇传·改名与北汉初政，段落 jiu-wudaishi-205deb4a7860-p003242；已核上下文及传主，纸本及异文待核。", "id": "4a9948df-1eab-5924-a75b-0d5abb2370da"}, {"title": "新五代史·卷70·东汉世家·李骧劝谏与被杀", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/82a6e88e766f7337f28566c6d64678bb760b98b8/content/books/zizhi-tongjian/vol-290/year-0951/part-02/sources/library/xinwudaishi-070-li-xiang-counsel/source.txt", "note": "《新五代史》卷70·东汉世家·李骧劝谏与被杀，段落 xin-wudaishi-b08f244b9241-p003446；已核上下文及传主，纸本及异文待核。", "id": "7c6cf516-a81d-50a7-b19c-6e92eab50dd8"}, {"title": "资治通鉴·卷290·广顺元年·正月北汉与宋州事", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/82a6e88e766f7337f28566c6d64678bb760b98b8/content/books/zizhi-tongjian/vol-290/year-0951/part-01/sources/library/tongjian-290-951-january-court/source.txt", "note": "《资治通鉴》卷290·广顺元年·正月北汉与宋州事，段落 zizhi-tongjian-a63549944a71-p003443；已核上下文及传主，纸本及异文待核。", "id": "bb681727-9eea-5a6d-ba00-7e07450247f4"}, {"title": "资治通鉴·卷290·广顺元年·即位与正月政策", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7f523fc68334366ce90d3a6e1465b179c9c38000/content/books/zizhi-tongjian/vol-290/year-0951/part-01/sources/library/tongjian-290-951-accession-policy/source.txt", "note": "《资治通鉴》卷290·广顺元年·即位与正月政策，段落 zizhi-tongjian-a63549944a71-p003442；已核上下文及传主，纸本及异文待核。", "id": "339d276e-47dc-5a40-bfb6-5fb37e96c3c0"}, {"title": "新五代史·卷11·周本纪·广顺元年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7f523fc68334366ce90d3a6e1465b179c9c38000/content/books/zizhi-tongjian/vol-290/year-0951/part-01/sources/library/xinwudaishi-011-first-year-951/source.txt", "note": "《新五代史》卷11·周本纪·广顺元年，段落 xin-wudaishi-b08f244b9241-p000368；已核上下文及传主，纸本及异文待核。", "id": "d3b793df-2c14-5468-91e6-30671d01ef09"}, {"title": "新五代史·卷11·周本纪·十二月北返与监国", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/57e21ee3cc42021b75390decc78b600e3618c9fb/content/books/zizhi-tongjian/vol-289/year-0950/part-13/sources/library/xinwudaishi-011-december-950/source.txt", "note": "《新五代史》卷11·周本纪·十二月北返与监国，段落 xin-wudaishi-b08f244b9241-p000367；已核上下文及传主，纸本及异文待核。", "id": "becceed3-0d3e-5ed2-adf2-777205288c13"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "刘赟", "aliases": ["劉赟", "劉贇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘崇的儿子，刘知远喜爱他，把他当作自己的儿子。《新五代史》记948年任徐州节度使，949年《通鉴》记以武宁节度使身份获加同平章事。后续经历随主书年代续录，生卒年尚未录入。", "biography": null, "status": "draft", "id": "8b95e2f2-9627-55f8-adca-a0b287179971"}, {"name": "李骧", "aliases": ["李驤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "真定人，任河东幕僚。947年五月甲午任太原少尹，协助北京留守。生卒年未载。", "biography": null, "status": "draft", "id": "396c059d-a8b1-5901-8bea-7b2cad44203b"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "巩延美", "aliases": ["鞏延美", "巩庭美", "鞏庭美", "巩廷美", "鞏廷美"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘赟的右都押牙。950年刘赟离开徐州西行迎立时，与杨温留守徐州。《新五代史》刘赟传写作巩庭美，同职同伴及同一留守场景对应；生卒年本批未录。", "biography": null, "status": "draft", "id": "4df9296b-060c-55ce-9ca5-a4523a55428f"}, {"name": "杨温", "aliases": ["楊溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘赟的元从都教练使。950年刘赟离开徐州西行迎立时，与巩延美留守徐州。生卒年本批未录。", "biography": null, "status": "draft", "id": "899b9466-92c5-5e46-b835-0d2e7cfdbf64"}, {"name": "董氏（刘赟妻）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘赟的妃子。刘赟被废后，巩延美、杨温奉她据守徐州，等待河东援兵。与郭威妻子董氏等同姓人物分别建档，生卒年未载。", "biography": null, "status": "draft", "id": "76941d01-f7b9-50a2-9d07-93eb276809fc"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "刘词", "aliases": ["劉詞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国都指挥使，元城人。942年与王清率军先登襄州。生卒年未载。", "biography": null, "status": "draft", "id": "1d26caf6-67d4-52b5-a6df-b9dff192cea5"}, {"name": "朱宪（后周使者）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周左千牛卫将军。951年受郭威派遣出使契丹，说明改朝原因，并赠金器玉带。与938年后晋内职官朱宪暂无连续履历证据，暂不合并，生卒年未载。", "biography": null, "status": "draft", "id": "d51ae347-5862-5f97-a3e0-11cce3591ce1"}, {"name": "王殷（后汉后周将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州籍将领。950年以侍卫步军都指挥使身份奉命驻澶州防备契丹，后来参与后周建国。《旧五代史》记他自称出生在魏州开元寺，籍贯与出生地分开。与晚唐后梁同名王殷分开建档，生卒年本批未录。", "biography": null, "status": "draft", "id": "4b85115a-7337-546f-af4c-9f6bd20f13c6"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "郑珙", "aliases": ["鄭珙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "青州人，刘崇的节度判官。刘崇因与郭威有嫌隙而忧惧时，郑珙劝他谋求自保；《新五代史》也记类似谋议，但安排在郭威讨平三镇之后，与《资治通鉴》的叙述顺序不同。生卒年未据本次原文确定。", "biography": null, "status": "draft", "id": "d8579c34-3e02-5140-b6af-9f52a59f202e"}, {"name": "赵华", "aliases": ["趙華"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥阳人，刘崇的观察判官。951年北汉建立时任户部侍郎、同平章事。生卒年未载。", "biography": null, "status": "draft", "id": "46a07b33-c4b5-5221-b9d4-6ab3055ba6b9"}, {"name": "刘承钧", "aliases": ["劉承鈞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘崇的次子。951年父亲在晋阳称帝时，任侍卫亲军都指挥使、太原尹。《旧五代史》也记他是刘崇之子并任两职。生卒年本批未录。", "biography": null, "status": "draft", "id": "3f4681a7-ca79-5d5d-a5c2-53bef1936681"}, {"name": "李存瑰", "aliases": ["李瓌", "李瑰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李存瑰，供奉官、赴西川赐诏者。", "biography": null, "status": "draft", "id": "a91449a7-a285-52aa-9c4a-0bf81e533f51"}, {"name": "张元徽", "aliases": ["張元徽"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武安人，刘崇的裨将。951年北汉建立时任马步军都指挥使。生卒年未载。", "biography": null, "status": "draft", "id": "b1a0aed5-927c-5e60-95b8-aea2894d7ad1"}, {"name": "陈光裕", "aliases": ["陳光裕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "951年北汉建立时获任宣徽使。生卒年未载。", "biography": null, "status": "draft", "id": "efbc64d6-cbc8-5546-b69b-b600b2f97b7e"}, {"name": "李光美", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "河南人，北汉客省使，曾任直省官，熟悉典章。史书将北汉朝廷制度归于他的安排。生卒年未载。", "biography": null, "status": "draft", "id": "a238805d-2279-5ae7-85d6-6abcc79480f8"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

